var QUESTIONS = QUESTIONS || [];
QUESTIONS.push(
{
id: 'D08',
group: 'D',
topic: 'Access token, refresh token và đánh đổi khi logout',
prio: 'P1',
level: 'L2',
type: 'concept',
incident: "<p>Một ứng dụng dùng JWT làm access token với thời hạn 24 giờ để tránh việc người dùng phải đăng nhập lại. Một nhân viên nghỉ việc, tài khoản bị vô hiệu hoá, nhưng token của họ vẫn dùng được tới 23 giờ sau đó. Đội giảm thời hạn xuống 15 phút và thêm refresh token, nhưng giờ họ không có cách nào thu hồi refresh token khi người dùng bị khoá.</p>",
askFirst: ["Vì sao JWT không thu hồi được?","Đánh đổi giữa thời hạn ngắn và số lần làm mới là gì?","Refresh token nên được lưu ở đâu?"],
predict: {"q":"Một JWT đã phát hành với thời hạn 1 giờ. Bạn xoá người dùng khỏi database. Token đó còn dùng được không?","a":"<p>Còn, cho tới khi hết hạn. JWT là một khẳng định tự chứa: server kiểm tra chữ ký và thời hạn, không truy vấn database để hỏi xem người dùng còn tồn tại hay không. Đó chính là ưu điểm của nó — không cần tra cứu — và cũng chính là nhược điểm — không thu hồi được. Muốn thu hồi được thì phải thêm một bước tra cứu trạng thái, và khi đó bạn đã đánh đổi mất phần lợi ích chính của JWT.</p>"},
anchor: "JWT tự chứa nên không thu hồi được — muốn thu hồi thì phải thêm tra cứu trạng thái, và khi đó bạn trả lại đúng chi phí mà JWT được chọn để tránh.",
attacks: [{"q":"Vậy làm sao thu hồi được quyền truy cập ngay lập tức?","a":"Có ba cách, đánh đổi khác nhau. Một là giữ thời hạn access token rất ngắn — vài phút — để cửa sổ thu hồi hẹp, chấp nhận nhiều lần làm mới hơn. Hai là duy trì một danh sách thu hồi và kiểm tra nó ở mỗi request, đổi lại mất tính phi trạng thái và thêm một phép tra cứu vào đường nóng. Ba là dùng phiên phía server với định danh phiên trong cookie, và xoá phiên khi cần thu hồi — đơn giản nhất nếu bạn không cần chia sẻ danh tính qua nhiều hệ thống độc lập."},{"q":"Refresh token nên lưu ở đâu phía client?","a":"Trong cookie <code>HttpOnly</code>, <code>Secure</code>, và <code>SameSite</code> phù hợp, vì JavaScript không đọc được nên một lỗ hổng XSS không lấy được nó. Lưu trong bộ nhớ cục bộ thì tiện nhưng mọi script trên trang đều đọc được, và đó là lý do phổ biến nhất khiến token bị đánh cắp. Điều cần thêm là cơ chế xoay refresh token mỗi lần dùng và phát hiện dùng lại: nếu một refresh token đã dùng lại xuất hiện lần thứ hai, đó là dấu hiệu bị đánh cắp, và nên thu hồi cả chuỗi."}],
q: 'Phân biệt access token và refresh token như thế nào, và khi logout bạn thu hồi token bằng cách nào?',
oral: 'Access token là token sống ngắn, thường 10 đến 30 phút, gửi kèm mỗi lần gọi API để máy chủ kiểm tra quyền. Refresh token sống lâu vài ngày, chỉ dùng để đổi lấy access token mới, không được gửi tới các API nghiệp vụ. Tách vậy để hạn chế thiệt hại: access token bị đánh cắp chỉ dùng được trong vài phút, còn nếu nó sống dài thì kẻ xấu dùng được tới khi hết hạn. Refresh token sống lâu nên phải lưu nghiêm ngặt hơn, trong cookie HttpOnly Secure SameSite, còn access token tôi giữ trong bộ nhớ ứng dụng để JavaScript không đọc được cookie. Về logout có hai lựa chọn: thu hồi bằng danh sách chặn, tức là token đã phát ra vẫn dùng được tới khi hết hạn, hoặc chọn access token TTL ngắn để việc thu hồi là tự động theo thời gian.',
deep: '<p>Sáng thứ Hai bạn vô hiệu hoá tài khoản một nhân viên nghỉ việc, nhưng access token 24 giờ của người đó vẫn gọi API tới tối. Server không hề hỏi database, vì JWT tự chứa chữ ký và thời gian hết hạn. Server tin chữ ký là tin quyền, nên xoá user trong database không làm token đã ký mất hiệu lực. Muốn thu hồi ngay thì bạn phải trả giá một lần tra cứu ở mọi request.</p><p>Access token chứng minh quyền ở mỗi request, còn refresh token chỉ đổi quyền mới ở một endpoint duy nhất. Tách hai loại để thu hẹp thiệt hại: access sống 10 đến 30 phút nên lộ cũng chỉ dùng được vài phút, refresh sống nhiều ngày nên phải nằm chỗ khó lấy hơn. Web giữ refresh trong cookie HttpOnly Secure SameSite và giữ access trong bộ nhớ, app mobile giữ refresh trong khoá của hệ điều hành. Refresh xoay vòng thì mỗi lần đổi cấp bản mới và huỷ bản cũ, bản cũ bị dùng lại nghĩa là có hai bên cùng giữ token nên bạn thu hồi cả chuỗi phiên.</p><ul><li><strong>Dùng khi:</strong> chọn TTL ngắn không trạng thái khi bạn chấp nhận trễ thu hồi vài phút. Chọn denylist theo session id khi bạn cần khoá ngay như tài khoản admin hay token bị lộ, entry chỉ cần sống bằng ACCESS_TTL.</li><li><strong>Không dùng khi:</strong> không cấp access sống vài ngày để đỡ refresh, không dùng một định dạng cho cả hai loại, không coi xoá refresh trong database là đã đăng xuất xong.</li></ul><p>Khi điều kiện đổi thì đáp án đổi: API mobile hay máy gọi máy không có trình duyệt thì bạn bỏ cookie, trả refresh trong thân response và bắt client tự lưu an toàn, còn rủi ro thu hồi của access đã phát ra vẫn giữ nguyên.</p>',
code: "def issue_tokens(user_id, session_id):\n    access = create_jwt({'sub': user_id, 'sid': session_id}, ttl=900)\n    refresh = create_opaque_token({'sid': session_id}, ttl=60 * 60 * 24 * 7)\n    return {'access_token': access, 'expires_in': 900, 'refresh_token': refresh}\n\ndef logout(session_id):\n    # denylist: chan session ngay, refresh token het hieu luc tuc thoi\n    denylist.add(session_id, ttl=60 * 60 * 24 * 7)\n    refresh_store.delete(session_id)",
expected: 'Chạy mô phỏng luồng này bằng stdlib (máy không có thư viện JWT nên tôi tự ký HMAC-SHA256 với cùng cấu trúc): issue_tokens trả {\'access_token\': ..., \'expires_in\': 900, \'refresh_token\': ...}, tức access token sống 15 phút còn refresh sống 7 ngày là 604800 giây. Trước logout, verify access token trả 200. Sau logout(session_id), refresh_store.pop khiến refresh không còn nên mọi lần đổi token đều thất bại; nhưng access token đã phát ra vẫn qua được kiểm tra chữ ký và exp — tôi chạy lại verify khi bỏ qua denylist và nhận đúng 200. Chỉ khi mỗi request tra denylist thì nó mới trả 401 với lý do sid nằm trong denylist. Phân tích: đây là toàn bộ đánh đổi của câu hỏi. Access token là JWT tự chứa nên không cần tra cứu, đổi lại thu hồi không tức thì: xoá session trong database không làm token đã ký mất hiệu lực, vì chữ ký vẫn đúng và exp vẫn còn. Muốn thu hồi ngay thì phải trả giá một lượt tra denylist ở mọi request, hoặc chấp nhận TTL ngắn để cửa sổ rủi ro chỉ còn vài phút. Một chi tiết hay bị bỏ: entry denylist chỉ cần sống bằng hoặc lâu hơn ACCESS_TTL là 900 giây là đủ để chặn hết access token đã phát, không cần bằng REFRESH_TTL 7 ngày. Cạm bẫy: đặt access token sống vài ngày rồi coi denylist là thừa, hoặc dùng cùng một định dạng token cho cả hai loại nên lọt refresh token ở đâu là gọi được API nghiệp vụ.',
followups: [{q: 'Vì sao không nên lưu refresh token trong localStorage của trình duyệt?', a: 'localStorage đọc được bằng JavaScript, nên chỉ một lỗi XSS là token bị lấy và kẻ xấu dùng được để đổi access token trong suốt thời gian còn hiệu lực. Cookie HttpOnly bị JavaScript không đọc được, kết hợp Secure và SameSite còn chặn gửi nhầm sang miền khác. Đổi lại bạn phải xử lý CSRF khi gọi endpoint refresh, nên đây là đánh đổi chứ không phải lựa chọn miễn phí.'}, {q: 'Làm sao phát hiện trường hợp refresh token đã bị đánh cắp rồi được dùng lại?', a: 'Bạn dùng refresh token xoay vòng: mỗi lần đổi token thì cấp refresh token mới và lưu hash của bản mới, xoá bản cũ. Nếu một lần refresh dùng key đã bị đánh dấu đã dùng thì chắc chắn có hai bên đang cùng giữ token, nên bạn thu hồi toàn bộ chuỗi session đó và bắt đăng nhập lại. Cách này biến việc phát hiện trộm cắp thành một sự kiện bình thường thay vì phải đoán.'}],
pitfalls: ['Cấp access token sống vài ngày rồi gọi đó là rút gọn quy trình, mỗi lần lộ token là vài ngày mất quyền truy cập.', 'Xóa refresh token trong database rồi coi như đã đăng xuất, trong khi access token đã phát ra vẫn dùng được tới khi hết hạn.', 'Dùng cùng một định dạng token cho cả hai loại nên bất kỳ đâu lọt refresh token cũng gọi được API nghiệp vụ.'],
selfcheck: ['Tôi vẫn chưa giải thích được vì sao xóa session trong database không khiến access token đã phát ra mất hiệu lực ngay lập tức.', 'Tôi giải thích được vòng đời access token và refresh token bằng ví dụ ứng dụng web đặt refresh token trong cookie HttpOnly và access token trong bộ nhớ.', 'Tôi có thể chọn giữa denylist và TTL ngắn cho hệ thống thuê bao, kèm phân tích độ trễ và mức độ rủi ro thu hồi của từng phương án.'],
refs: ['mdn-cookies', 'mdn-http-headers', 'owasp-api-security']
},
{
id: 'D09',
group: 'D',
topic: 'Validate đầu vào, định dạng lỗi thống nhất và OpenAPI',
prio: 'P1',
level: 'L2',
type: 'concept',
incident: "<p>Ba endpoint trong cùng một API trả lỗi theo ba định dạng khác nhau: một cái trả chuỗi thuần, một cái trả <code>{\"error\": \"...\"}</code>, một cái trả mảng lỗi của framework. Client phải viết ba nhánh xử lý. Ngoài ra, tài liệu OpenAPI hiển thị sai kiểu của một trường vì nó được khai báo là chuỗi nhưng thực tế trả về số, và điều đó chỉ lộ ra khi một đối tác tích hợp bị lỗi.</p>",
askFirst: ["Vì sao định dạng lỗi thống nhất lại quan trọng với client?","OpenAPI được sinh từ đâu, và khi nào nó nói dối?","Kiểm tra đầu vào nên trả về mã trạng thái nào?"],
predict: {"q":"Client gửi một trường có kiểu sai, ví dụ số cho một trường khai báo chuỗi. API nên trả về mã nào?","a":"<p>Về mặt ngữ nghĩa, đây là lỗi thực thể chứ không phải lỗi cú pháp: cú pháp JSON đúng nhưng nội dung không thoả schema, nên mã phù hợp là 422. Nhiều API trả 400 cho mọi lỗi đầu vào, điều đó chấp nhận được nhưng kém chính xác. Điều quan trọng hơn mã là tính nhất quán: cùng một loại lỗi phải luôn trả cùng một mã và cùng một cấu trúc thân, để client xử lý bằng một nhánh duy nhất. Cấu trúc nên có ít nhất một mã lỗi máy đọc được, một thông điệp cho người đọc, và đường dẫn tới trường gây lỗi.</p>"},
anchor: "Định dạng lỗi là một phần của hợp đồng API, nên ba định dạng cho cùng một loại lỗi nghĩa là ba lần client phải đoán.",
attacks: [{"q":"Làm sao giữ OpenAPI khớp với thực tế?","a":"Sinh nó từ chính kiểu dữ liệu mà code dùng, chứ không viết tay. Trong FastAPI, khai báo <code>response_model</code> cho mỗi endpoint để framework vừa lọc dữ liệu trả về vừa sinh tài liệu đúng. Thêm một test so sánh response thật với schema đã sinh — nhiều thư viện làm được việc này — để tài liệu sai làm test đỏ. Và với những trường hợp không biểu diễn được bằng kiểu, hãy ghi rõ trong mô tả endpoint thay vì để người đọc tự suy đoán."},{"q":"Có nên trả về chi tiết lỗi kiểm tra cho client không?","a":"Có, nhưng chỉ chi tiết về hình dạng dữ liệu, không chi tiết về hệ thống. Nói \"trường <code>email</code> không đúng định dạng\" là hữu ích và an toàn. Nói \"truy vấn thất bại tại cột <code>users.email_verified_at</code> vì ràng buộc duy nhất\" là rò rỉ cấu trúc database cho người ngoài. Nguyên tắc là thông điệp cho client mô tả <em>cái gì sai với dữ liệu bạn gửi</em>, còn chi tiết nội bộ đi vào log phía server kèm định danh để tra cứu."}],
q: 'Bạn validate dữ liệu đầu vào ở tầng nào và thiết kế thân lỗi API thống nhất ra sao để phía VueJS xử lý được?',
oral: 'Tôi validate ở biên, tức là tầng request trước khi dữ liệu chạm vào nghiệp vụ, bằng schema khai báo trong framework như pydantic của FastAPI hay serializer của Django REST Framework. Việc kiểm tra định dạng ngay ở biên giúp lỗi trả về sớm, rẻ và có mã trạng thái đúng, thường là 400 hoặc 422 thay vì lỗi 500. Phần lỗi tôi thống nhất một hình vỏ: trường error chứa code máy đọc được, message tiếng Việt cho người dùng, danh sách chi tiết theo từng field và trace_id để tra log. Client VueJS chỉ cần một hàm duy nhất đọc lỗi, hiển thị message và gắn trace_id vào ticket. Quan trọng là mã lỗi phải ổn định, không dùng thông báo tiếng Anh làm khoá phân loại.',
deep: '<p>Đối tác tích hợp báo client của họ crash vì một trường OpenAPI khai báo chuỗi nhưng server trả số. Ba endpoint trong cùng API trả lỗi theo ba hình dạng khác nhau, nên phía VueJS phải viết ba nhánh đoán. Sửa từng chỗ không hết, vì lỗi nằm ở hợp đồng: validation không chặn ở biên và thân lỗi không cố định. Schema khai báo kiểu, độ dài, dải giá trị và quy tắc liên field sẽ chặn request hỏng trước khi chạm nghiệp vụ hay database. Request hỏng trả cùng một vỏ gồm code, message, details theo field và trace_id.</p><p><code>code</code> dành cho máy rẽ nhánh, còn <code>message</code> dành cho người đọc. Bạn giữ code ổn định để frontend switch một chỗ, đổi message tiếng Việt thoải mái mà không phá client. Ví dụ POST tạo đơn thiếu email trả 422 với details chỉ rõ field email và rule format, VueJS đọc field là gắn lỗi đúng ô input, trace_id đi vào ticket để tra log. Sinh OpenAPI từ schema trong code và thêm test hợp đồng ở CI, nên tài liệu lệch là build đỏ thay vì lộ lúc chạy thật.</p><ul><li><strong>Dùng khi:</strong> dùng schema khai báo cho hợp đồng ổn định như tạo đơn. Validate thủ công cho query lọc linh hoạt với giá trị mặc định.</li><li><strong>Không dùng khi:</strong> không nhét quy tắc phụ thuộc dữ liệu như còn hàng trong kho vào schema, không trả traceback của framework cho client, không lấy message làm khoá so sánh.</li></ul><p>Khi điều kiện đổi thì đáp án đổi: request xử lý hàng loạt nhiều item thì bạn trả mảng lỗi theo từng item kèm 207 hoặc 200 có cờ lỗi, vì client vẫn cần phần thành công bên cạnh phần hỏng.</p>',
code: "{\n  \"error\": {\n    \"code\": \"validation_error\",\n    \"message\": \"Email khong hop le.\",\n    \"details\": [\n      { \"field\": \"email\", \"rule\": \"format\", \"value\": \"abc\" }\n    ],\n    \"trace_id\": \"01JC8Z9W4TQ7\"\n  }\n}",
expected: 'Đây là một object JSON chứ không phải chương trình nên không in ra gì khi chạy; đọc bằng json.loads cho thấy cấu trúc: khóa top-level duy nhất là \'error\', bên trong có đúng bốn khóa code, message, details, trace_id; details là một mảng và phần tử đầu là {"field":"email","rule":"format","value":"abc"} — đã kiểm chứng bằng json.loads trong Python. Phân tích: hình vỏ lỗi thống nhất tách hai loại dữ liệu khác hẳn nhau. code = \'validation_error\' là hợp đồng máy đọc, ổn định, client rẽ nhánh theo nó; message là tiếng Việt cho người dùng và sẽ bị sửa hoặc dịch nên không được dùng làm khóa; details là mảng nên một request báo được nhiều field lỗi cùng lúc, mỗi phần tử gắn field cộng rule cộng value để VueJS gắn lỗi đúng ô input; trace_id là sợi chỉ nối response với log server. Tôi chạy thử một hàm client chỉ switch theo code: khi message đổi thành \'Invalid email.\' thì handler vẫn gắn lỗi đúng field, chứng minh rẽ nhánh theo message là thừa và giòn. Với lỗi ở biên, FastAPI/pydantic trả 422 kèm cấu trúc này, lỗi thiếu quyền là 403, lỗi chưa xác thực là 401 — ba mã khác nhau vì client xử lý khác nhau. Cạm bẫy: trả traceback nguyên bản của framework cho client và viết OpenAPI bằng tay ngoài code rồi để nó lệch với cài đặt thật.',
followups: [{q: 'Vì sao không nên dùng thông báo lỗi tiếng Anh làm khoá phân loại lỗi ở phía client?', a: 'Thông báo là dữ liệu dành cho con người, sẽ bị dịch, đổi câu hoặc viết lại bất cứ lúc nào, nên dùng nó làm khoá khiến client sinh ra rất nhiều nhánh if chết. Mã lỗi là hợp đồng giữa hai bên, bạn giữ nó ổn định và đổi cả câu thoại hiển thị cho người dùng. Client chỉ cần rẽ nhánh theo mã, còn text lấy thẳng từ server.'}, {q: 'Spec OpenAPI sinh tự động rồi dùng để sinh client TypeScript có những rủi ro gì?', a: 'Sinh client tự động dễ khiến team tin rằng client đã đồng bộ với server trong khi thực tế client đã cũ và chưa được cài lại. Rủi ro thứ hai là kiểm thử hợp đồng sinh ra chỉ kiểm tra kiểu dữ liệu, bỏ qua hành vi thực tế như quyền truy cập hay trạng thái nghiệp vụ. Bạn nên có một pipeline CI chạy định kỳ so client cũ với spec hiện tại để phát hiện lệch.'}],
pitfalls: ['Chỉ kiểm tra dữ liệu ở giao diện rồi tin rằng API đã an toàn, trong khi ai cũng gọi thẳng API được bằng curl.', 'Trả thông báo lỗi nguyên bản của framework kèm traceback, làm lộ đường dẫn file và tên bảng trong database.', 'Viết spec OpenAPI bằng tay riêng ngoài code nên nhanh chóng lệch với cài đặt thật.'],
selfcheck: ['Tôi vẫn chưa giải thích được vì sao lỗi xác thực, lỗi quyền và lỗi nghiệp vụ phải dùng ba mã trạng thái khác nhau thay vì gộp về một lỗi.', 'Tôi giải thích được hình vỏ lỗi thống nhất gồm code, message, details theo field và trace_id bằng ví dụ endpoint tạo đơn trả 422.', 'Tôi có thể chốt một hợp đồng lỗi cho toàn bộ API rồi viết một hàm duy nhất ở phía VueJS hiển thị đúng thông báo và gửi trace_id đi kèm khi báo lỗi.'],
refs: ['owasp-api-security', 'owasp-top10', 'mdn-http-headers']
},
{
id: 'D10',
group: 'D',
topic: 'Timeout, retry, backoff và jitter cho lời gọi dịch vụ ngoài',
prio: 'P1',
level: 'L3',
type: 'debug',
incident: "<p>Một service gọi API đối tác để tra cứu địa chỉ. Đối tác bắt đầu trả lỗi 503 trong khoảng 90 giây. Vì code có retry ba lần ngay lập tức, mỗi request của người dùng tạo thêm ba lời gọi, và trong hai phút service gửi 60.000 request tới một hệ thống đang quá tải. Đối tác chặn địa chỉ IP của công ty trong 30 phút, và giờ ngay cả những request lẽ ra thành công cũng hỏng.</p>",
askFirst: ["Vì sao retry ngay lập tức làm tình hình tệ hơn?","Backoff và jitter giải quyết vấn đề gì khác nhau?","Timeout nên đặt bao nhiêu, và dựa trên cái gì?"],
predict: {"q":"Một nghìn client cùng gặp lỗi tại cùng một thời điểm và cùng retry sau đúng 1 giây. Chuyện gì xảy ra với hệ thống phía sau?","a":"<p>Nó bị dội một đợt một nghìn request cùng lúc, đúng bằng đợt vừa làm nó quá tải. Đây là hiệu ứng đồng bộ: retry có backoff nhưng không có jitter vẫn tạo ra các đợt tấn công đồng loạt theo chu kỳ. Jitter — thêm một khoảng ngẫu nhiên vào thời gian chờ — làm lệch pha các client, biến một đợt dội thành một dòng request trải đều. Đó là lý do jitter không phải chi tiết làm đẹp mà là điều kiện để backoff thực sự hoạt động.</p>"},
anchor: "Retry không có backoff và jitter biến một sự cố ngắn thành một đợt tấn công đồng loạt vào hệ thống đang yếu.",
attacks: [{"q":"Timeout nên đặt bao nhiêu?","a":"Dựa trên ngân sách độ trễ của nghiệp vụ, không dựa trên cảm giác. Nếu endpoint có mục tiêu p99 là 800 ms và nó gọi ba phụ thuộc, mỗi phụ thuộc không nên chiếm quá một phần ngân sách đó. Một cách làm thực dụng là đặt timeout theo phân vị cao của phụ thuộc đó cộng biên, ví dụ p99 nhân 1,5, và điều chỉnh khi có số liệu thật. Điều cần tránh là để timeout mặc định vô hạn, vì khi đó một phụ thuộc treo sẽ giữ tài nguyên của bạn cho tới khi tầng trên cắt — và tầng trên thường cắt muộn hơn nhiều."},{"q":"Circuit breaker khác retry ở đâu?","a":"Retry giả định rằng lỗi là tạm thời và thử lại sẽ thành công. Circuit breaker giả định ngược lại: sau một số lỗi liên tiếp, nó ngừng gọi hẳn trong một khoảng, để hệ thống phía sau có thời gian hồi phục và để bạn không tiêu tốn tài nguyên vào những lời gọi gần như chắc chắn thất bại. Hai cơ chế bổ sung cho nhau: retry cho lỗi thoáng qua, circuit breaker cho sự cố kéo dài. Thiếu circuit breaker là lý do phổ biến khiến một phụ thuộc hỏng kéo sập cả hệ thống gọi nó."}],
q: 'Đoạn gọi dịch vụ thanh toán bên ngoài này sẽ gây hậu quả gì khi dịch vụ đó chậm hoặc trả lỗi, và bạn sửa từng điểm ra sao?',
oral: 'Đoạn này có bốn lỗi. Một là không đặt timeout, nên một lời gọi treo sẽ giữ cả connection của worker vô hạn và tích tụ cho tới khi hết pool. Hai là không có backoff và jitter, nên năm lần thử lại chạy liền nhau, và khi dịch vụ ngoài hồi phục thì tất cả worker cùng đâm vào một lúc, tạo retry storm làm dịch vụ đó chết lần nữa. Ba là không lọc theo mã lỗi, nên lỗi 400 do dữ liệu sai hay lỗi 401 thiếu token cũng bị thử lại vô ích. Bốn là lời gọi thanh toán không idempotent, thử lại có thể trừ tiền khách hàng nhiều lần. Tôi sẽ thêm timeout theo từng nhánh connect và read, chỉ retry lỗi tạm thời như 429, 502, 503, 504 với exponential backoff kèm jitter, gắn idempotency key, và có circuit breaker để ngắt hẳn khi tỉ lệ lỗi vượt ngưỡng.',
deep: '<p>Chín mươi giây đối tác trả 503, service của bạn retry ngay ba lần và gửi 60.000 request trong hai phút. Đối tác chặn IP của bạn 30 phút, và cả request lẽ ra thành công cũng hỏng. Vòng retry trong code không nghỉ giữa các lần, không lọc mã lỗi, không gắn khoá thanh toán. Timeout cắt một lần chờ treo ở nhánh connect và read, nên worker không bị giữ tới khi cạn pool. Backoff giãn khoảng chờ theo cấp số nhân, jitter cộng thêm ngẫu nhiên để các worker không thức giấc cùng lúc.</p><p>Retry tin lỗi thoáng qua nên thử lại, còn circuit breaker tin sự cố kéo dài nên ngừng gọi hẳn. Bạn chỉ retry lỗi tạm thời như 429, 502, 503, 504 và lỗi mạng, tôn trọng header Retry-After khi có. Bạn không retry 400, 401, 403, 404 hay 422 vì gửi lại y nguyên vẫn hỏng. Thanh toán chỉ retry khi có idempotency key để lần hai trả kết quả cũ. Breaker mở sau N lỗi liên tiếp, trả lỗi nhanh một khoảng rồi cho một probe đi qua kiểm tra hồi phục.</p><ul><li><strong>Dùng khi:</strong> gọi qua internet thì timeout, retry giới hạn theo mã, backoff kèm jitter và breaker là bắt buộc. Đặt timeout từ p99 của phụ thuộc cộng biên, ví dụ p99 nhân 1.5.</li><li><strong>Không dùng khi:</strong> không retry POST thanh toán thiếu key, không đặt timeout 60 giây cho API p99 dưới một giây, không retry mọi mã cho bằng nhau.</li></ul><p>Khi điều kiện đổi thì đáp án đổi: gọi qua message broker thì bạn bỏ retry tay vì broker lo redelivery, còn gọi ngoài internet thì giữ đủ bộ; endpoint p99 800ms gọi ba phụ thuộc thì mỗi phụ thuộc chỉ được một phần ngân sách đó.</p>',
code: "const MAX_ATTEMPTS = 5;\nconst result = { ok: false };\n\nasync function charge(orderId) {\n  let attempt = 0;\n  while (attempt !== MAX_ATTEMPTS) {\n    attempt = attempt + 1;\n    try {\n      const res = await gateway.charge(orderId);\n      result.ok = true;\n      return res;\n    } catch (err) {\n      console.error('charge failed', err);\n    }\n  }\n  return result;\n}",
expected: 'Khi gateway.charge luôn ném lỗi, hàm charge thử lại 5 lần liền nhau không nghỉ giữa các lần, in ra 5 dòng log rồi trả về đối tượng có ok bằng false. Nguyên nhân gồm bốn điểm: không có timeout nên một lời gọi treo giữ chặn worker vô hạn, không có backoff và jitter nên thử lại dồn cục và tạo retry storm, không lọc mã lỗi nên cả lỗi 400 hay 401 không thể sửa cũng bị thử lại, và lời gọi thanh toán không mang idempotency key nên có thể trừ tiền khách nhiều lần.',
followups: [{q: 'Vì sao không nên retry lỗi 400 hay 401 trong khi vẫn retry lỗi 503?', a: 'Lỗi 400 và 401 là lỗi tất định: yêu cầu sai định dạng hoặc thiếu quyền, thử lại với đúng dữ liệu đó vẫn thất bại, nên retry chỉ tăng tải và ăn hạn mức. Lỗi 503 là lỗi tạm thời do phía dịch vụ đang quá tải hoặc bảo trì, cùng yêu cầu đó sau một khoảng nghỉ có khả năng thành công. Nguyên tắc là retry lỗi tạm thời, chữ lỗi tất định thì sửa nguyên nhân gốc trước khi gọi lại.'}, {q: 'Backoff theo cấp số nhân khác với backoff cố định ở chỗ nào khi hệ thống chịu tải cao?', a: 'Backoff cố định giữ nhịp thử lại không đổi, nên khi dịch vụ ngoài chỉ cần thêm vài giây là tất cả client vẫn dồn ép vào đúng nhịp cũ và nó lại quá tải. Backoff theo cấp số nhân khoảng chờ tăng gấp đôi sau mỗi lần thất bại, nên lưu lượng thử lại giảm dần đúng lúc dịch vụ cần được nghỉ. Trên vẫn phải cộng jitter, vì nếu không thì các client hỏng cùng lúc vẫn tự đồng bộ lại vô hình.'}],
pitfalls: ['Thêm retry cho mọi lỗi mà không xem mã trạng thái, biến một sự cố nhỏ thành retry storm làm hệ thống sập.', 'Đặt timeout nhưng quá dài, chẳng hạn 60 giây, khiến pool kết nối bị giữ mà lưu lượng thực tế gần bằng không.', 'Retry một POST thanh toán không kèm idempotency key nên khách bị trừ tiền hai lần cho cùng một đơn.'],
selfcheck: ['Tôi vẫn chưa giải thích được khi nào nên đặt circuit breaker và vì sao ngưỡng mở mạch phải khác ngưỡng đóng mạch.', 'Tôi giải thích được backoff theo cấp số nhân kèm jitter bằng ví dụ năm lần thử lại với độ trễ tăng dần và lệch ngẫu nhiên.', 'Tôi có thể sửa một hàm gọi dịch vụ thanh toán thành có timeout, retry giới hạn theo mã lỗi, idempotency key và log cảnh báo khi tỉ lệ lỗi tăng.'],
refs: ['owasp-api-security', 'mdn-http-overview', 'mdn-http-headers']
},
{
id: 'D11',
group: 'D',
topic: 'Idempotency key, request trùng và xác thực webhook',
prio: 'P1',
level: 'L3',
type: 'situation',
incident: "<p>Một cổng thanh toán gọi webhook tới hệ thống của bạn mỗi khi giao dịch đổi trạng thái. Trong một đợt đối tác gặp sự cố mạng, cùng một webhook được gửi lại 14 lần trong 20 phút. Hệ thống xử lý cả 14 lần và cộng tiền vào số dư 14 lần. Ngoài ra, endpoint webhook không kiểm tra chữ ký, nên bất kỳ ai biết đường dẫn cũng gửi được một thông báo giả.</p>",
askFirst: ["Vì sao webhook gần như luôn được gửi lại nhiều lần?","Làm sao phân biệt hai lần gửi của cùng một sự kiện với hai sự kiện thật?","Xác thực webhook dựa trên gì?"],
predict: {"q":"Bạn nhận một webhook và ghi kết quả vào database, sau đó trả về 500 vì một lỗi tạm thời ở bước ghi log. Đối tác sẽ làm gì?","a":"<p>Nó gửi lại webhook đó, vì phản hồi không phải mã thành công nghĩa là bạn chưa xử lý xong. Lần gửi thứ hai đến khi kết quả đã được ghi từ lần đầu, nên nếu handler không có ranh giới idempotency, hiệu ứng sẽ được áp dụng hai lần. Đây là lý do thứ tự đúng là: xác thực chữ ký, kiểm tra và ghi kết quả trong một thao tác nguyên tử theo định danh sự kiện, rồi mới trả về thành công — và mọi việc phụ như ghi log phải được đặt sau hoặc được bọc để không làm hỏng phản hồi.</p>"},
anchor: "Webhook là giao vận at-least-once, nên bên nhận phải tự chống trùng theo định danh sự kiện chứ không thể giả định mỗi sự kiện chỉ đến một lần.",
attacks: [{"q":"Xác thực webhook nên dựa trên gì?","a":"Trên một chữ ký HMAC tính từ thân request bằng một khoá bí mật chia sẻ, kèm dấu thời gian để chống phát lại. So sánh chữ ký phải dùng phép so sánh có thời gian không đổi để tránh rò rỉ thông tin qua thời gian phản hồi. Điều không dùng được là một token tĩnh trong header: nó không ràng buộc với nội dung nên ai đọc được một request là phát lại được bất kỳ nội dung nào. Và nên từ chối những request có dấu thời gian lệch quá một khoảng, thường là vài phút."},{"q":"Idempotency key cho API của chính bạn khác gì chống trùng webhook?","a":"Cơ chế giống nhau, nhưng nguồn gốc khoá khác nhau. Với API của bạn, client sinh khoá và gửi trong header cho mỗi thao tác nghiệp vụ; server lưu khoá kèm kết quả và trả lại chính kết quả đó cho mọi lần gửi lặp. Với webhook, khoá do bên gửi đặt trong thân sự kiện — thường là định danh sự kiện — và bạn dùng nó để chống trùng. Trong cả hai trường hợp, điều kiện then chốt là việc kiểm tra và việc ghi phải nguyên tử, nếu không hai request đồng thời vẫn cùng vượt qua được bước kiểm tra."}],
q: 'Khi khách bấm nút thanh toán hai lần và cả hai request đều tới server, bạn dùng idempotency key và xác thực webhook ra sao để không tạo ra hai giao dịch?',
oral: 'Khách bấm hai lần là chuyện thường vì nút bị bấm lại khi mạng chậm, và request trùng còn xảy ra do retry, do load balancer hay do proxy. Cách xử lý là bắt client gửi kèm một idempotency key sinh ngẫu nhiên duy nhất cho mỗi lần bấm, thường là UUID. Server lưu key cùng kết quả xử lý vào một bảng có ràng buộc UNIQUE. Khi có request vào, nếu key đã tồn tại thì trả lại đúng kết quả cũ chứ không tạo giao dịch mới, và so khớp cả nội dung request để phát hiện client dùng lại key cho dữ liệu khác. Nguyên tắc là phải cấu hình idempotency ở phía dịch vụ thanh toán, vì nếu chỉ khóa ở API của bạn thì khi request chết giữa đường bạn không biết lệnh đã tới đối tác hay chưa. Với webhook, bạn kiểm tra chữ ký HMAC của toàn bộ thân request bằng secret, so sánh theo kiểu thời gian hằng, lưu event id đã xử lý để chặn replay, trả lại 200 nhanh rồi xử lý bất đồng bộ.',
deep: '<p>Số dư khách hàng tăng gấp 14 lần sau một đợt mạng chập chờn, vì cùng một webhook thanh toán gửi lại 14 lần trong 20 phút. Endpoint của bạn không kiểm tra chữ ký, nên ai biết đường dẫn cũng gửi được thông báo giả. Webhook là giao vận at-least-once, đối tác gửi lại cho tới khi nhận mã thành công. Bên nhận phải tự chống trùng theo định danh sự kiện, không được giả định mỗi sự kiện chỉ đến một lần. Client sinh một idempotency key cho mỗi ý định bấm nút, server lưu key kèm kết quả và lần sau trả lại kết quả cũ.</p><p>Idempotency key do client của bạn sinh cho API của bạn, còn event id do đối tác sinh cho webhook của họ. Hai cơ chế chung một nguyên tắc nguyên tử: chèn key trước với ràng buộc UNIQUE rồi mới xử lý, request đến sau chạm ràng buộc thì đọc replay. Cùng key mà hash nội dung khác thì bạn trả 409 vì client dùng lại key sai. Webhook thì tính HMAC trên toàn bộ thân bằng secret, so bằng hàm thời gian hằng, từ chối timestamp lệch vài phút, lưu event id đã thấy, trả 200 nhanh rồi đẩy việc nặng vào hàng đợi.</p><ul><li><strong>Dùng khi:</strong> bật idempotency ở cả API của bạn và phía cổng thanh toán, vì chỉ khoá một đầu thì request chết giữa đường vẫn tạo giao dịch thứ hai.</li><li><strong>Không dùng khi:</strong> không chống trùng bằng cách disable nút ở giao diện, không tái dùng một key cho cả phiên, không xác thực webhook bằng IP hay token tĩnh.</li></ul><p>Khi điều kiện đổi thì đáp án đổi: đối tác không hỗ trợ idempotency thì bạn tự tạo khoá nghiệp vụ như mã đơn gắn với đơn hàng và kiểm tra trạng thái trước khi gọi, còn đối tác timeout ngắn thì bạn càng phải trả 200 sớm và xử lý bất đồng bộ.</p>',
code: "@app.post('/payments')\nasync def create_payment(request: Request, idempotency_key: str = Header(...)):\n    body = await request.json()\n    digest = hashlib.sha256(json.dumps(body, sort_keys=True).encode()).hexdigest()\n    saved = await idempotency_store.get(idempotency_key)\n    if saved:\n        if saved['digest'] != digest:\n            raise HTTPException(status_code=409)\n        return saved['response']\n    payment = await db.insert_payment(amount=body['amount'])\n    await idempotency_store.put(idempotency_key, digest, payment)\n    return payment\n\n@app.post('/webhooks/payment')\nasync def payment_webhook(request: Request, x_signature: str = Header('')):\n    raw = await request.body()\n    digest = hmac.new(WEBHOOK_SECRET.encode(), raw, hashlib.sha256).hexdigest()\n    if not hmac.compare_digest(digest, x_signature):\n        raise HTTPException(status_code=401)\n    if await event_store.seen(digest):\n        return {'status': 'duplicate'}\n    await event_store.mark(digest)\n    queue.enqueue(raw)\n    return {'status': 'accepted'}",
expected: 'Endpoint này không chạy đúng như viết: idempotency_store.put(key, digest, payment) chỉ lưu digest và payment, nhưng nhánh replay lại đọc saved[\'response\']. Tôi port nguyên cặp put/get sang Python và tái hiện: lần đầu lưu xong bản ghi có đúng hai khóa [\'digest\', \'payment\'], lần thứ hai với cùng key đi vào nhánh saved rồi ném KeyError: \'response\' — tức request trùng nhận 500 thay vì được replay kết quả cũ. Sửa tối thiểu là lưu cả response đã trả: put(key, digest, response). Nhưng đó chưa phải lỗi nặng nhất. Kiểm-tra-rồi-mới-ghi có cửa sổ TOCTOU: tôi chạy hai luồng cùng key trên SQLite, bản không có ràng buộc UNIQUE tạo ra 2 payment cho cùng một giao dịch, còn bản chèn key trước với PRIMARY KEY tạo đúng 1 payment và request thứ hai nhận bản replay 200. Điểm mấu chốt là để chính database bảo đảm tính duy nhất bằng INSERT trước, thay vì tin vào get() ở tầng ứng dụng. Cùng key mà body khác thì phải trả 409 — đã kiểm chứng: digest khác nhau nên trả 409 thay vì âm thầm trả kết quả cũ. Phần webhook, hmac.compare_digest là bắt buộc: đo trên chuỗi hex 64 ký tự, toán tử == nhanh hơn và thời gian tăng theo độ dài tiền tố khớp (khoảng 117 ns khi khớp 0 ký tự lên 125 ns khi khớp 63 ký tự), còn compare_digest quét hết chuỗi (khoảng 230 đến 300 ns) và không lộ vị trí khác nhau đầu tiên. Chênh lệch chỉ vài chục ns mỗi lần nhưng với lưu lượng lớn đó là kênh side-channel để dò dần từng ký tự của chữ ký. Cạm bẫy: chỉ chống trùng ở giao diện, dùng lại một key cho cả phiên, hoặc tin địa chỉ IP người gửi webhook.',
followups: [{q: 'Hai request cùng idempotency key tới gần như cùng lúc thì chuyện gì xảy ra nếu bạn kiểm tra rồi mới ghi?', a: 'Đây là cửa sổ TOCTOU: cả hai request đều kiểm tra thấy key chưa tồn tại nên cùng đi xa hơn và cùng tạo giao dịch, khiến cơ chế idempotent vô hiệu. Cách sửa là chèn bản ghi key trước khi xử lý và đặt ràng buộc UNIQUE trên key, nên request đến sau sẽ bị lỗi ràng buộc, từ đó đọc lại kết quả đã lưu. Cách này nhờ chính database bảo đảm tính duy nhất thay vì tin vào việc kiểm tra ở tầng ứng dụng.'}, {q: 'Vì sao phải so sánh chữ ký HMAC bằng hàm thời gian hằng thay vì so sánh chuỗi thường?', a: 'So sánh chuỗi thường dừng ngay ở ký tự khác nhau đầu tiên, nên thời gian thực thi phản ánh độ dài tiền tố khớp và kẻ tấn công có thể dò dần từng byte chữ ký đúng bằng cách đo thời gian. Hàm so sánh thời gian hằng luôn duyệt hết chuỗi nên không lộ thông tin qua thời gian. Với webhook, chỉ cần một vài nghìn lần đo cũng đủ dò được chữ ký ngắn, nên đây là yêu cầu bắt buộc chứ không phải tối ưu hình thức.'}],
pitfalls: ['Chỉ chống request trùng ở tầng giao diện bằng cách vô hiệu hoá nút sau cú bấm đầu tiên, ai gọi thẳng API vẫn tạo giao dịch trùng.', 'Dùng lại cùng một idempotency key cho mọi request của một phiên làm mất tác dụng chống trùng.', 'Tin địa chỉ IP của người gửi webhook là đủ để xác thực, trong khi IP của đối tác có thể đổi theo hạ tầng.'],
selfcheck: ['Tôi vẫn chưa giải thích được tại sao lưu key và kết quả bằng cơ chế khóa phân tán lại dễ hỏng hơn ràng buộc UNIQUE của database.', 'Tôi giải thích được luồng xác thực webhook gồm HMAC, so sánh thời gian hằng, chặn event trùng và xử lý bất đồng bộ qua hàng đợi.', 'Tôi có thể thiết kế lại endpoint thanh toán với idempotency key, bảng lưu có ràng buộc UNIQUE và cơ chế chặn event webhook trùng.'],
refs: ['owasp-api-security', 'mdn-http-headers']
},
{
id: 'D12',
group: 'D',
topic: 'Rate limiting, caching và ETag, Cache-Control',
prio: 'P2',
level: 'L2',
type: 'predict',
incident: "<p>Một endpoint danh sách sản phẩm trả về 200 KB JSON mỗi lần gọi. Trình duyệt tải lại toàn bộ dữ liệu mỗi lần người dùng quay lại trang, dù dữ liệu chỉ đổi vài lần mỗi ngày. Sau khi thêm <code>Cache-Control: max-age=3600</code>, người dùng phàn nàn rằng giá cũ vẫn hiển thị sau khi quản trị viên cập nhật, và không có cách nào buộc làm mới ngoài việc chờ hết một giờ.</p>",
askFirst: ["Cái gì quyết định một response có được cache hay không?","Làm sao để client kiểm tra dữ liệu có đổi không mà không tải lại toàn bộ?","Làm sao vừa cache được vừa cập nhật được ngay khi cần?"],
predict: {"q":"Client gửi <code>If-None-Match</code> với một ETag khớp với phiên bản hiện tại của tài nguyên. Server trả về gì?","a":"<p>Server trả về 304 Not Modified với thân rỗng. Đây là điểm quan trọng về hiệu quả: client vẫn thực hiện một vòng request, nhưng tiết kiệm được toàn bộ phần thân — với response 200 KB thì đó là phần lớn chi phí. Cơ chế này cho phép bạn đặt thời hạn cache ngắn mà không lo phục vụ dữ liệu cũ, vì mỗi lần dùng lại client đều hỏi server xem có gì mới. Điều cần chú ý là 304 không có thân, nên client phải dùng bản đã lưu chứ không được ghi đè bằng rỗng.</p>"},
anchor: "ETag biến việc kiểm tra \"có gì mới không\" thành một vòng request rẻ, cho phép cache ngắn hạn mà vẫn phục vụ được dữ liệu mới.",
attacks: [{"q":"Rate limiting nên đặt theo cái gì, và trả về mã nào?","a":"Theo danh tính khi có thể — người dùng, khoá API — và theo địa chỉ nguồn khi ẩn danh. Mã trả về khi vượt hạn mức là 429, kèm header <code>Retry-After</code> để client biết khi nào thử lại. Nên có nhiều hạn mức chồng nhau: một hạn mức chung cho toàn bộ API, và những hạn mức chặt hơn cho các endpoint đắt đỏ như gửi email, tạo tài nguyên, hay tìm kiếm phức tạp. Điều cần tránh là chỉ có một hạn mức duy nhất, vì khi đó một endpoint nặng có thể tiêu hết quota của cả ứng dụng."},{"q":"Làm sao buộc làm mới cache ngay khi dữ liệu đổi?","a":"Dùng tên phiên bản trong đường dẫn hoặc tham số — thêm một số phiên bản hoặc hash nội dung vào URL — để khi dữ liệu đổi thì đó là một URL khác, và cache cũ không còn được dùng. Với dữ liệu không thể đổi tên, dùng ETag kèm thời hạn ngắn: client sẽ kiểm tra lại mỗi lần và nhận 304 nếu chưa đổi, nên chi phí gần như bằng không. Với cache ở tầng CDN, có thể xoá theo đường dẫn khi dữ liệu đổi. Điều không nên làm là đặt thời hạn dài rồi dựa vào việc xoá cache thủ công — đó là cách chắc chắn sẽ có lúc ai đó quên."}],
q: 'Phân tích chuỗi request và response dưới đây: lần gọi thứ hai nhận mã trạng thái gì, cache dùng chung có lưu được response này không, và lượt gọi đó có bị tính vào rate limit không?',
oral: 'Lần gọi thứ hai nhận mã 304 Not Modified và không có body, vì ETag client gửi trong If-None-Match khớp với ETag hiện tại của biểu diễn, nên máy chủ chỉ xác nhận bản trong cache vẫn dùng được. Response 304 phải kèm lại ETag và các header liên quan cache. Cache dùng chung như CDN không được lưu response này vì Cache-Control là private, nghĩa là chỉ cache của riêng trình duyệt được phép giữ. Lượt gọi thứ hai vẫn phải đi qua máy chủ nên vẫn bị tính vào rate limit, chỉ có băng thông tải body được tiết kiệm. Chính vì vậy API cần cache ở phía máy chủ nếu bạn thật sự muốn giảm tải và giảm số lượt bị chặn. Ba điểm này tách bạch: ETag quyết định có cần gửi lại dữ liệu, Cache-Control quyết định ai được giữ dữ liệu, còn rate limit đếm lượt gọi chứ không đếm byte.',
deep: '<p>Lượt tải lại thứ hai của trang danh sách vẫn tải đủ 200KB dù dữ liệu không đổi, và sau khi bạn đặt max-age một giờ thì giá cũ treo nguyên một giờ. Ba khái niệm trong chuỗi request này hoàn toàn tách nhau. ETag là nhãn phiên bản của một biểu diễn, client gửi lại trong If-None-Match để hỏi có gì mới. Cache-Control quyết định ai được lưu và lưu bao lâu. Rate limiting đếm lượt gọi trong một cửa sổ, không đếm byte. Server so ETag khớp thì trả 304 rỗng kèm lại ETag và Cache-Control, lệch thì trả 200 kèm dữ liệu và ETag mới.</p><p>ETag tiết kiệm byte thân response, còn rate limit đếm lượt request. Lần 304 trong code vẫn chạm server nên vẫn ăn quota, nó chỉ rẻ băng thông. Directive private trong response mẫu cấm CDN lưu, chỉ trình duyệt của chính user được giữ. Danh mục công khai thì bạn đặt public cho CDN phục vụ tại chỗ, dữ liệu theo tài khoản thì đặt private kèm Vary theo header quyền như Authorization.</p><ul><li><strong>Dùng khi:</strong> đặt ETag kèm max-age ngắn cho dữ liệu đổi ít, đổi tên URL theo version hoặc hash nội dung khi muốn làm mới ngay, trả 429 kèm Retry-After khi vượt quota.</li><li><strong>Không dùng khi:</strong> không tưởng 304 là miễn quota, không đặt public cho response riêng từng user, không giữ ETag cũ sau khi giá đã đổi.</li></ul><p>Khi điều kiện đổi thì đáp án đổi: tài nguyên công khai mọi người thấy giống nhau thì cache CDN mạnh tay, tài nguyên riêng từng người thì private và hỏi lại server thường xuyên, muốn giảm tải thật thì cache ở server chứ ETag một mình không giảm lượt gọi.</p>',
code: "GET /api/products/42 HTTP/1.1\nAccept: application/json\nAuthorization: Bearer eyJhbGciOiJIUzI1NiJ9\n\nHTTP/1.1 200 OK\nContent-Type: application/json\nCache-Control: private, max-age=60\nETag: \"42-1700\"\n\n{\"id\": 42, \"name\": \"May pha ca phe\"}\n\nGET /api/products/42 HTTP/1.1\nIf-None-Match: \"42-1700\"\nAuthorization: Bearer eyJhbGciOiJIUzI1NiJ9",
expected: "Lần gọi thứ hai trả về 304 Not Modified với body rỗng, kèm lại header ETag và Cache-Control, vì nhãn trong If-None-Match khớp đúng ETag hiện tại của biểu diễn nên máy chủ không gửi lại dữ liệu. Cache dùng chung như CDN không được lưu response này vì directive private giới hạn việc lưu cho cache của riêng trình duyệt. Lượt gọi thứ hai vẫn phải tới máy chủ nên vẫn bị tính vào rate limit, ETag chỉ tiết kiệm băng thông chứ không giảm số lượt gọi. Nếu client dùng If-None-Match với một ETag cũ khác thì máy chủ trả 200 kèm dữ liệu và ETag mới.",
followups: [{q: 'Vì sao dữ liệu riêng theo từng người dùng không được cache bằng CDN dù vẫn đặt max-age dài?', a: 'CDN là cache dùng chung, nhiều người hỏi cùng một đường dẫn. Nếu response chứa dữ liệu riêng mà bạn đặt public, bản đầu tiên được cache sẽ được trả cho mọi người sau đó, tức là rò dữ liệu chéo tài khoản. Cách đúng là đặt private, thêm header Vary theo header liệu phụ thuộc quyền như Authorization, hoặc tách đường dẫn theo phân đoạn người dùng và chỉ cache phần công khai thật sự.'}, {q: '429 với header Retry-After khác với 503 thế nào, và client nên làm gì với mỗi mã?', a: '429 nghĩa là bạn bị giới hạn theo chính sách, cần giảm tần suất gọi và tôn trọng Retry-After trả về. 503 nghĩa là dịch vụ tạm thời không sẵn sàng, cần thử lại với backoff và jitter. 401 và 403 thì không có nghĩa thử lại được, client phải xử lý đăng nhập hoặc thông báo thiếu quyền. Phân biệt rõ bốn nhóm này là điều kiện tiên quyết để lớp retry viết đúng.'}],
pitfalls: ['Tưởng có ETag và 304 nghĩa là không tốn hạn mức rate limit, trong khi request vẫn phải tới máy chủ.', 'Đặt Cache-Control public cho response chứa dữ liệu riêng theo tài khoản, khiến CDN trả nhầm dữ liệu người dùng này cho người dùng khác.', 'Dùng lại ETag cũ sau khi dữ liệu đổi, khiến client hiển thị dữ liệu stale trong thời gian dài.'],
selfcheck: ['Tôi vẫn chưa giải thích được khi nào ETag mạnh khác ETag yếu và vì sao máy chủ dùng ETag yếu phải cấm cache dùng chung.', 'Tôi giải thích được chuỗi 200 rồi 304 bằng cách giải thích vai trò của ETag, If-None-Match và Cache-Control trong cùng một response.', 'Tôi có thể rà lại header cache của các endpoint hiện có, tách rõ endpoint công khai đưa vào CDN và endpoint riêng theo tài khoản đặt private, kèm giới hạn rate limit hợp lý.'],
refs: ['mdn-cache-control', 'mdn-http-headers']
},
{
id: 'D13',
group: 'D',
topic: 'SQL injection, XSS, CSRF, SSRF, secrets và log nhạy cảm',
prio: 'P2',
level: 'L3',
type: 'debug',
incident: "<p>Một endpoint tìm kiếm nối chuỗi trực tiếp vào câu SQL. Một người dùng nhập một chuỗi có dấu nháy đơn và nhận về toàn bộ bảng người dùng kèm mật khẩu đã băm. Cùng tuần đó, một trang hiển thị tên khách hàng không escape nội dung, nên một khách hàng đặt tên có thẻ script và script đó chạy trong trình duyệt của nhân viên hỗ trợ. Ngoài ra, log của service ghi cả header Authorization và số thẻ.</p>",
askFirst: ["Vì sao tham số hoá lại ngăn được SQL injection?","Escape ở đầu ra khác gì kiểm tra ở đầu vào?","Dữ liệu nhạy cảm cần được xử lý thế nào trước khi ghi log?"],
predict: {"q":"Một truy vấn dùng tham số hoá <code>WHERE name = $1</code> với giá trị <code>O'Brien</code>. Chuyện gì xảy ra?","a":"<p>Nó tìm đúng người tên <code>O'Brien</code> và không có lỗi cú pháp. Đây là điểm cốt lõi: tham số hoá không phải là escape ký tự, mà là gửi câu lệnh và dữ liệu qua hai kênh riêng biệt. Server phân tích cú pháp câu lệnh trước, khi giá trị còn chưa được biết, nên dữ liệu không bao giờ được hiểu như mã. Vì vậy không có chuỗi đầu vào nào có thể thay đổi cấu trúc truy vấn — khác hẳn với việc nối chuỗi rồi tự escape, nơi chỉ cần một trường hợp biên bị bỏ sót là đủ.</p>"},
anchor: "Tham số hoá tách câu lệnh khỏi dữ liệu ở tầng giao thức, nên không có chuỗi đầu vào nào thay đổi được cấu trúc truy vấn.",
attacks: [{"q":"Vì sao escape ở đầu vào là cách tiếp cận sai?","a":"Vì bạn phải escape đúng cho mọi ngữ cảnh mà dữ liệu sẽ đi qua — SQL, HTML, thuộc tính HTML, URL, JavaScript nhúng, header — và mỗi ngữ cảnh có quy tắc riêng. Escape một lần ở đầu vào không biết trước dữ liệu sẽ được dùng ở đâu, nên gần như chắc chắn sai ở ít nhất một chỗ. Ngoài ra, escape làm hỏng dữ liệu gốc: tên người dùng lưu dạng đã escape sẽ hiển thị sai ở chỗ khác. Nguyên tắc đúng là lưu dữ liệu thô, và escape ở đúng ngữ cảnh tại thời điểm hiển thị."},{"q":"Log nhạy cảm gây hại như thế nào?","a":"Log thường được đọc bởi nhiều người hơn dữ liệu gốc, được lưu lâu hơn, và được sao chép sang hệ thống khác mà không có cùng mức kiểm soát truy cập. Một token ghi vào log có thể bị dùng để mạo danh trong nhiều giờ. Một số thẻ ghi vào log có thể đưa hệ thống vào phạm vi tuân thủ mà bạn không lường trước. Cách xử lý là có một danh sách các trường luôn bị che ở tầng ghi log — không phải dựa vào việc từng lập trình viên nhớ — và định kỳ rà lại xem log có chứa gì ngoài dự kiến."}],
q: 'Đoạn tạo đơn hàng này có những lỗ hổng bảo mật nào, kẻ xấu khai thác được gì và bạn sửa từng lỗi ra sao?',
oral: 'Đoạn này có bốn lỗi nghiêm trọng. Một là SQL injection: nối thẳng uid, product_id và qty của người dùng vào câu lệnh, nên gửi uid chứa dấu nháy là chèn thêm được dòng đơn hàng giả, còn product_id không cần nháy nên chèn được điều kiện OR để đọc dữ liệu ngoài phạm vi. Hai là secret nằm trong log, mật khẩu database được ghi ra ở dạng rõ, ai đọc log cũng biết. Ba là SSRF: endpoint nhận URL tùy ý rồi tự gọi, kẻ xấu dùng nó để dò dịch vụ nội bộ. Bốn là XSS khi sau này tên người dùng được chèn thẳng vào HTML mà không escape. Cách sửa là dùng câu lệnh có tham số, đưa secret vào biến môi trường và không log bao giờ, kiểm tra URL đích bằng danh sách cho phép và chặn mạng nội bộ, cuối cùng escape dữ liệu khi xuất ra HTML.',
deep: '<p>Tên khách hàng chứa một thẻ script và nó chạy ngay trong trình duyệt của nhân viên hỗ trợ. Cùng tuần đó log ghi nguyên header Authorization và mật khẩu database. Đoạn tạo đơn nối thẳng uid, product_id và qty vào SQL, nhận webhook URL tuỳ ý rồi tự gọi ra ngoài. Tham số hoá gửi câu lệnh và dữ liệu qua hai kênh riêng, server phân tích cú pháp trước khi biết giá trị nên input không bao giờ thành mã. Nhờ vậy chuỗi tên có dấu nháy vẫn tìm đúng người mà không vỡ cú pháp. Escape thì khác, nó chỉ làm input vô hại trong một ngữ cảnh xuất cụ thể.</p><p>Tham số hoá tách mã khỏi dữ liệu ở tầng giao thức, còn escape chỉ bảo vệ một nơi hiển thị. Bạn lưu dữ liệu thô rồi escape lúc xuất theo đúng đích HTML, thuộc tính, URL hay JavaScript, cộng Content-Security-Policy để giảm hậu quả. SSRF thì chặn bằng danh sách đích cho phép, chặn dải mạng riêng và metadata endpoint, vì kiểm tra có https không chặn được gì. Secret nằm trong biến môi trường hoặc kho bí mật và không bao giờ vào log. Trong code mẫu, uid bọc nháy cho phép chèn dòng đơn giả, product_id số cho phép lái điều kiện OR, còn payload nhiều câu kiểu DROP TABLE bị sqlite3 chặn vì mỗi execute chỉ chạy một câu.</p><ul><li><strong>Dùng khi:</strong> mọi SQL dùng placeholder của driver, mọi URL gọi ra ngoài qua allowlist, mọi log đi qua bộ lọc che token, thẻ và dữ liệu cá nhân.</li><li><strong>Không dùng khi:</strong> không nối chuỗi báo cáo dù đang dùng ORM, không escape một lần ở đầu vào cho mọi ngữ cảnh, không đổi trạng thái qua GET khi còn dùng cookie phiên.</li></ul><p>Khi điều kiện đổi thì đáp án đổi: SPA không dùng cookie phiên thì CSRF gần như biến mất nhưng injection, SSRF và rò secret vẫn nguyên, API nội bộ sau tường lửa chỉ giảm nhẹ CSRF chứ ba lỗi kia vẫn nguy hiểm như thường.</p>',
code: "from flask import Flask, request\nimport sqlite3, requests, os\n\napp = Flask(__name__)\nDB_PASSWORD = os.getenv('DB_PASSWORD')\n\n@app.post('/orders')\ndef create_order():\n    uid = request.json['uid']\n    product_id = request.json['product_id']\n    qty = request.json['qty']\n    webhook = request.json.get('webhook')\n\n    conn = sqlite3.connect('app.db')\n    conn.execute(\n        f\"INSERT INTO orders (uid, product_id, qty) VALUES ('{uid}', {product_id}, {qty})\"\n    )\n    price = conn.execute(f\"SELECT price FROM products WHERE id = {product_id}\").fetchone()\n    conn.commit()\n    app.logger.info(f\"order by uid={uid} dbpass={DB_PASSWORD}\")\n    if webhook:\n        requests.post(webhook, json={'uid': uid}, timeout=5)\n    return {'ok': True}",
expected: 'Lỗi injection ở đây là thật nhưng không phải dạng xoá bảng. sqlite3 chỉ chạy MỘT câu lệnh cho mỗi lần gọi execute, nên payload nhiều câu lệnh kiểu "1; DROP TABLE orders; --" bị chặn ngay với lỗi near ";": syntax error, bảng orders không bị xoá. Cái thật sự khai thác được nằm ở uid: vì uid được bọc trong dấu nháy đơn, gửi uid = x\', 1, 1), (\'attacker\', 999, 999) -- biến câu lệnh thành INSERT ... VALUES (\'x\', 1, 1), (\'attacker\', 999, 999) --\', ...) và chèn thêm một dòng đơn hàng giả do kẻ tấn công kiểm soát — tôi tái hiện đúng kết quả này trên SQLite. product_id thì không cần dấu nháy nên gửi 1 OR 1=1 làm SELECT trả dòng products đầu tiên bất kể id, tức đọc được dữ liệu ngoài phạm vi cho phép. Gốc chung vẫn là dữ liệu người dùng được nối thẳng vào chuỗi câu lệnh thay vì truyền qua tham số. Ba lỗi còn lại: DB_PASSWORD được ghi nguyên văn vào log, trường webhook nhận URL bất kỳ nên kẻ xấu dùng làm SSRF dò mạng nội bộ, và giá trị người dùng trả về trong JSON sẽ thành XSS nếu phía VueJS chèn bằng innerHTML.',
followups: [{q: 'Vì sao dùng tham số của driver lại an toàn hơn việc tự escape ký tự đặc biệt?', a: 'Escape thủ công dễ sót: bạn phải nhớ đúng bộ ký tự cho từng ngữ cảnh và vị trí, và một đường mới trong truy vấn là một lỗ hổng mới. Tham số của driver tách hẳn mã và dữ liệu ở tầng giao thức, nên giá trị có chứa dấu nháy hay chấm phẩy cũng chỉ được coi là văn bản thuần chứ không đổi được cấu trúc câu lệnh. Cách này đúng theo chính đặc tả nên không phụ thuộc trí nhớ của lập trình viên.'}, {q: 'Bạn phát hiện SSRF bằng cách nào khi dịch vụ chạy sau một load balancer trên cloud?', a: 'Bạn xác định danh sách dịch vụ nội bộ và dải mạng thật của môi trường đó, rồi chặn ở tầng proxy hoặc security group thay vì chỉ kiểm tra trong code ứng dụng. Bên trong code bạn vẫn áo một danh sách đích cho phép và phân giải tên miền rồi kiểm tra địa chỉ sau khi phân giải, vì DNS có thể trả về địa chỉ nội bộ. Thêm giới hạn thời gian chờ ngắn và cấm chuyển hướng để khó lợi dụng hơn nữa.'}],
pitfalls: ['Dùng ORM nhưng vẫn ghép chuỗi SQL thô cho báo cáo tùy biến, cho rằng dùng ORM là miễn nhiễm với SQL injection.', 'Chỉ kiểm tra URL của webhook là có https là giả vờ chống được SSRF.', 'Log toàn bộ body của request để tiện tra cứu, vô tình ghi mật khẩu và token vào log rồi xoay vòng secret mà quên log cũ.'],
selfcheck: ['Tôi vẫn chưa giải thích được vì sao phải chặn SSRF ở tầng proxy và security group chứ không chỉ kiểm tra trong code ứng dụng.', 'Tôi giải thích được bốn lỗi trong đoạn tạo đơn hàng bằng ví dụ uid gây SQL injection, URL webhook tùy ý gây SSRF và mật khẩu lọt vào log.', 'Tôi có thể rà soát một endpoint hiện có, thay SQL nối chuỗi bằng truy vấn có tham số, bỏ secret khỏi log và thêm danh sách đích hợp lệ cho mọi lời gọi ra ngoài.'],
refs: ['owasp-top10', 'owasp-api-security', 'mdn-csp']
},
{
id: 'D14',
group: 'D',
topic: 'Khác biệt giữa bảo vệ giao diện và bảo vệ tài nguyên ở tầng API',
prio: 'P2',
level: 'L1',
type: 'concept',
incident: "<p>Một ứng dụng ẩn nút xoá với người dùng không phải quản trị viên, và chặn route quản trị ở tầng router. Một người dùng mở công cụ phát triển, gọi trực tiếp API xoá với định danh của một bản ghi bất kỳ, và xoá thành công. Việc ẩn nút và chặn route không hề ảnh hưởng tới API.</p>",
askFirst: ["Tầng giao diện bảo vệ được gì?","Vì sao \"không hiển thị nút\" không phải là biện pháp kiểm soát?","Kiểm tra quyền phải nằm ở đâu để có hiệu lực?"],
predict: {"q":"Một API xoá tài nguyên yêu cầu đăng nhập nhưng không kiểm tra vai trò. Nếu giao diện ẩn nút xoá với người dùng thường, API có an toàn không?","a":"<p>Không. Giao diện chạy trên máy của người dùng, dưới sự kiểm soát của người dùng. Họ có thể đọc mã nguồn, mở công cụ phát triển, hoặc gọi API bằng bất kỳ công cụ nào khác. Ẩn nút chỉ là một quy ước về trải nghiệm, không phải một hàng rào kỹ thuật. Bất kỳ biện pháp kiểm soát nào chỉ tồn tại ở phía client đều có thể bị vô hiệu hoá bởi chính người dùng mà nó định hạn chế — nên quyền phải được kiểm tra ở server cho từng request.</p>"},
anchor: "Mọi thứ chạy trên máy người dùng đều nằm dưới sự kiểm soát của người dùng, nên kiểm soát quyền chỉ có hiệu lực khi nằm ở server.",
attacks: [{"q":"Vậy lớp giao diện có giá trị gì trong bảo mật?","a":"Giá trị về trải nghiệm và về giảm bề mặt rò rỉ, không phải về ngăn chặn. Ẩn chức năng giúp người dùng không bấm nhầm vào việc họ không được phép làm, và tránh cho họ thấy những lỗi 403 khó hiểu. Ở một số trường hợp, việc không tải bundle của khu vực quản trị giúp giảm lượng thông tin về cấu trúc hệ thống mà người ngoài quan sát được. Nhưng phải nói rõ: đây là lớp phòng ngừa thừa. Nếu API không kiểm tra thì lớp giao diện không cứu được gì."},{"q":"Làm sao kiểm tra rằng API thực sự được bảo vệ?","a":"Bằng test tự động chạy với danh tính của từng vai trò và cố tình gọi những hành động không được phép, kỳ vọng nhận 403 chứ không phải 200. Quan trọng là phải kiểm tra cả trường hợp chéo: người dùng A cố truy cập tài nguyên của người dùng B, vì đó là lỗi tham chiếu đối tượng trực tiếp và không thể phát hiện bằng cách chỉ kiểm tra vai trò. Một cách làm hiệu quả là sinh test cho mọi cặp endpoint và vai trò, để một endpoint mới thêm vào mà thiếu kiểm tra quyền sẽ làm test đỏ ngay."}],
q: 'Vì sao ẩn nút Xóa trên giao diện VueJS không bảo vệ được dữ liệu, và bạn kiểm tra quyền ở tầng API bằng cách nào?',
oral: 'Ẩn nút trên giao diện chỉ là tiện ích hiển thị, còn dữ liệu thật nằm ở API, và bất kỳ ai cũng gọi thẳng API bằng curl, Postman hay một script nào đó mà không cần mở trình duyệt của bạn. Nên quyền phải được kiểm tra ở tầng API, nơi giữ dữ liệu và nơi mọi request bắt buộc đi qua. Cụ thể là xác thực token để biết đây là ai, rồi kiểm tra quyền theo hành động, tức là quyền xóa hồ sơ, và kiểm tra thêm quyền sở hữu, tức là hồ sơ này có thuộc về người gọi không. Trả về 401 khi chưa xác thực và 403 khi đã xác thực nhưng thiếu quyền. Giao diện dùng điều kiện hiển thị để nút bám đúng trạng thái server, nhưng điều kiện đó chỉ là tiện nghiệm, không phải hàng rào bảo mật.',
deep: '<p>Nút Xóa biến mất với tài khoản staff, nhưng người đó mở devtools, gọi thẳng API xoá và nhận 200. Router guard và điều kiện hiển thị không hề hấn gì vì chúng chạy trên máy của người dùng. Kẻ tấn công không cần sửa giao diện của bạn, họ chỉ cần không dùng nó mà gọi bằng curl hay script. Mọi kiểm soát chỉ tồn tại ở client đều vô hiệu với chính người mà nó định hạn chế. Quyền thật phải nằm ở server, nơi mọi request bắt buộc đi qua.</p><p>Giao diện quyết định có hiện nút cho tiện, còn API quyết định có cho xoá dữ liệu thật. Bạn xác thực token để biết ai gọi rồi trả 401 nếu thiếu, kiểm tra quyền hành động như orders xoá rồi trả 403 nếu thiếu, kiểm tra sở hữu bản ghi rồi trả 403 hoặc 404 nếu là đồ của người khác. Quyền lấy từ bảng phân quyền ở server, không lấy role hay user id do client tự khai trong body. Code mẫu làm đúng vậy: Vue chỉ tính canDelete để ẩn hiện, FastAPI kiểm tra quyền rồi kiểm tra owner rồi mới xoá. Test phải gọi thẳng API bằng từng vai trò và cả chéo A sang B.</p><ul><li><strong>Dùng khi:</strong> giữ hiển thị bám trạng thái server cho đỡ bấm nhầm, lọc danh sách ngay trong truy vấn theo owner, test mọi cặp endpoint và vai trò.</li><li><strong>Không dùng khi:</strong> trang công khai chỉ đọc không nhạy cảm thì không cần phân quyền chi tiết nhưng vẫn giữ rate limit, API nội bộ sau tường lửa cũng không bỏ kiểm tra.</li></ul><p>Khi điều kiện đổi thì đáp án đổi: sang mô hình nhiều đơn vị thì kiểm tra sở hữu mở rộng thành thuộc đơn vị, và bạn cache quyền theo vai trò thay vì tra cứu mỗi request.</p>',
code: "// VueJS: chi quyet dinh hien thi, khong bao ve du lieu\nconst canDelete = computed(() => user.value.role === 'admin')\n\n# FastAPI: quyet dinh thuc su\n@app.delete('/orders/{order_id}')\ndef delete_order(order_id: int, user = Depends(current_user)):\n    if 'orders:delete' not in user.permissions:\n        raise HTTPException(status_code=403)\n    order = db.get(Order, order_id)\n    if order is None:\n        raise HTTPException(status_code=404)\n    if order.owner_id != user.id and 'orders:delete:any' not in user.permissions:\n        raise HTTPException(status_code=403)\n    db.delete(order)\n    return {'deleted': order_id}",
expected: 'Đây là hai đoạn minh hoạ chứ không phải một chương trình chạy được: dòng VueJS là mã client, phần FastAPI là mã server, chúng không cùng ngôn ngữ nên không có output chung. Chạy riêng phần VueJS: role \'admin\' cho canDelete = true, role \'staff\' và \'customer\' cho false — nút Xoá chỉ được ẩn hoặc hiện, và tôi sửa được biến role trong devtools để nút hiện lại. Chạy mô phỏng phần API trên SQLite: gọi không token -> 401; user id 9 là customer -> 403 thiếu quyền orders:delete; user id 8 là staff có orders:delete xoá đơn 1043 của chính mình -> 200; cùng user đó xoá đơn 1042 của người khác -> 403 không sở hữu; admin có orders:delete:any -> 200, gọi lại lần hai -> 404. Phân tích: ẩn nút là quyết định hiển thị dựa trên trạng thái cục bộ, còn quyền là quyết định trên dữ liệu — và giao diện chạy trên máy người dùng nên họ kiểm soát hoàn toàn: bỏ điều kiện v-if, sửa request bằng devtools, hoặc gọi thẳng endpoint bằng curl mà không cần mở trang web. API mới là nơi duy nhất mọi request bắt buộc đi qua, nên phải có đủ ba lớp: xác thực trả 401, quyền theo hành động trả 403, và sở hữu bản ghi trả 403 hoặc 404 nếu muốn giấu sự tồn tại của tài nguyên người khác. Hai mã 401 và 403 phải tách nhau vì client xử lý khác nhau: 401 thì làm mới token hoặc đăng nhập lại, còn 403 thì làm mới token cũng vô ích. Cạm bẫy: tin role hoặc user_id do client gửi trong body, và dựa vào router guard của Vue để coi như đã bảo vệ dữ liệu.',
followups: [{q: 'Vì sao phải trả 401 và 403 là hai mã khác nhau thay vì gộp thành một lỗi chung?', a: 'Hai mã nói hai chuyện khác nhau và client xử lý khác nhau. 401 nghĩa là chưa xác thực được, client nên chạy luồng làm mới token hoặc đưa người dùng tới đăng nhập. 403 nghĩa là đã xác thực nhưng không đủ quyền, làm mới token không giúp ích gì và client chỉ nên hiện thông báo. Gộp chung sẽ khiến client thử đăng nhập lại vô ích rồi báo lỗi sai ý nghĩa cho người dùng.'}, {q: 'Bạn kiểm tra quyền sở hữu ở đâu khi danh sách đơn hàng có cả nghìn bản ghi của nhiều người?', a: 'Ở API trả danh sách bạn lọc ngay trong truy vấn bằng điều kiện owner_id bằng id của người gọi, thay vì lấy hết rồi lọc bằng code, nên không lộ cả dữ liệu lẫn không tốn bộ nhớ. Ở API lấy một bản ghi thì lấy theo khóa chính kèm điều kiện owner_id luôn, để đối tượng không tồn tại và đối tượng của người khác cùng dẫn tới một trả lời giống nhau, tránh việc dò xem bản ghi có thật không.'}],
pitfalls: ['Dựa vào điều kiện hiển thị hoặc router guard của VueJS để coi như đã bảo vệ, quên rằng cả hai đều chạy trên máy người dùng.', 'Tin giá trị user_id hoặc role do client gửi trong body rồi dùng nó để quyết định quyền.', 'Trả cùng một mã lỗi cho mọi trường hợp thiếu quyền, khiến client không phân biệt được cần đăng nhập lại hay chỉ thiếu quyền.'],
selfcheck: ['Tôi vẫn chưa giải thích được vì sao cấp quyền theo hành động và kiểm tra sở hữu là hai lớp tách biệt chứ không thể gộp làm một.', 'Tôi giải thích được vì sao giao diện chỉ là tiện nghiệm bằng ví dụ gọi thẳng endpoint xóa bằng curl không cần mở trang web.', 'Tôi có thể rà lại một API đơn giản, thêm kiểm tra quyền theo hành động và theo chủ sở hữu, trả 401 và 403 đúng phân biệt, kèm bộ kiểm thử gọi thẳng API không qua giao diện.'],
refs: ['owasp-api-security', 'owasp-top10', 'mdn-cors']
}
);